import React from "react";
import styles from "./Input.module.css";

export type InputVariant = "outlined" | "filled" | "standard";
export type InputColor =
  | "primary"
  | "secondary"
  | "error"
  | "warning"
  | "info"
  | "success";
export type InputSize = "small" | "medium" | "large";

export interface InputProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size"> {
  variant?: InputVariant;
  color?: InputColor;
  size?: InputSize;
  label?: string;
  error?: boolean;
  helperText?: string;
  fullWidth?: boolean;
  startIcon?: React.ReactNode;
  endIcon?: React.ReactNode;
}

export const Input = React.forwardRef<HTMLInputElement, InputProps>(
  (
    {
      className,
      variant = "outlined",
      color = "primary",
      size = "medium",
      label,
      error = false,
      helperText,
      fullWidth = false,
      startIcon,
      endIcon,
      required,
      disabled,
      id,
      ...props
    },
    ref
  ) => {
    const inputId = id || React.useId();

    const variantClass = styles[`variant-${variant}`] || "";
    const colorClass = styles[`color-${color}`] || "";
    const sizeClass = styles[`size-${size}`] || "";
    const fullWidthClass = fullWidth ? styles["full-width"] : "";
    const errorClass = error ? styles["state-error"] : "";
    const disabledClass = disabled ? styles["state-disabled"] : "";
    const hasLabelClass = label ? styles["has-label"] : "";

    return (
      <div
        className={`${styles["input-wrapper"]} ${fullWidthClass} ${disabledClass} ${errorClass} ${hasLabelClass}`.trim()}
      >
        {label && (
          <label
            htmlFor={inputId}
            className={`${styles.label} ${variantClass} ${colorClass} ${sizeClass}`}
          >
            {label}
            {required && <span className={styles.required}> *</span>}
          </label>
        )}
        <div
          className={`${styles["input-container"]} ${variantClass} ${colorClass} ${sizeClass}`}
        >
          {startIcon && (
            <span className={`${styles["icon-wrapper"]} ${styles["icon-start"]}`}>
              {startIcon}
            </span>
          )}
          <input
            id={inputId}
            ref={ref}
            disabled={disabled}
            required={required}
            className={`${styles.input} ${sizeClass} ${className || ""}`}
            {...props}
          />
          {endIcon && (
            <span className={`${styles["icon-wrapper"]} ${styles["icon-end"]}`}>
              {endIcon}
            </span>
          )}
        </div>
        {helperText && (
          <div className={`${styles["helper-text"]} ${colorClass}`}>
            {helperText}
          </div>
        )}
      </div>
    );
  }
);

Input.displayName = "Input";
